# Tests of span.py on fields with KNOWN class groups: cyclic fields of prime degree d and prime conductor l (d | l-1).
# If the class number is 1, span.py must succeed.  If the set T contains a prime with a non-principal prime ideal, the statement
# "the rows generate A^T" is false, so the greatest common divisor in step (c) must be different from 1 (it is a multiple of the
# order of the subgroup of the class group generated by the primes of T).
#   python3 span_test.py l d B Y h     (elements with coefficients of absolute value <= B, split primes < Y, h: the known class number)
import sys, itertools, math
from flint import fmpz
from verify import need, is_prime
import span
class PrimeConductorField:                            # the subfield of degree d of Q(zeta_l); eta_i = sum_{h in H} zeta^(g^i h)
    def __init__(self,l,d):
        need(is_prime(l) and is_prime(d) and (l-1)%d==0,"field"); self.p=l; self.M=l; self.N=d
        self.g=g=next(x for x in range(2,l) if all(pow(x,(l-1)//r,l)!=1 for r in range(2,l) if (l-1)%r==0 and is_prime(r)))
        self.H=[pow(g,d*t,l) for t in range((l-1)//d)]
        self.exps=[[pow(g,i,l)*h%l for h in self.H] for i in range(d)]
        need(sorted(e for ex in self.exps for e in ex)==list(range(1,l)),"cosets")
        self.aux=[]; a=(2**61//l)*l+1
        while len(self.aux)<8:
            a+=l
            if not is_prime(a): continue
            z=next(pow(x,(a-1)//l,a) for x in range(2,200) if pow(x,(a-1)//l,a)!=1)
            self.aux.append((a,[sum(pow(z,e,a) for e in ex)%a for ex in self.exps]))
    def split(self,q): return q!=self.p and pow(q,(self.p-1)//self.N,self.p)==1
    def norm(self,c,coef):
        N=self.N; b=abs(c)+len(self.H)*sum(abs(a) for i,a in coef); bound=2*b**N+1; mod=1; res=0
        for a_,R in self.aux:
            v=1
            for j in range(N): v=v*(c+sum(a*R[(i+j)%N] for i,a in coef))%a_
            res=res+mod*((v-res)*pow(mod,-1,a_)%a_); mod*=a_
            if mod>bound: break
        need(mod>bound,"not enough auxiliary primes")
        if res>mod//2: res-=mod
        return abs(res)
def relations(F,B,Y):                                 # all elements c + sum a_i eta_i with |c|, |a_i| <= B whose norm is l^a * (split primes < Y)
    N=F.N; out=[]
    for c in range(-B,B+1):
        for a in itertools.product(range(-B,B+1),repeat=N):
            if not any(a): continue
            if any((-c,tuple(-v for v in a))>(c,a) or (c,a[k:]+a[:k])>(c,a) or (-c,tuple(-v for v in a[k:]+a[:k]))>(c,a) for k in range(N)): continue   # one element for each orbit under the Galois group and the sign
            coef=[(i,v) for i,v in enumerate(a) if v]; x=F.norm(c,coef)
            if x==0: continue
            while x%F.p==0: x//=F.p
            fac=[]; q=2
            while x>1 and q<Y:
                if x%q==0:
                    k=0
                    while x%q==0: x//=q; k+=1
                    fac.append((q,k))
                q+=1
            if x==1 and fac and all(F.split(q) for q,k in fac):
                out.append((c,coef,fac))
    return out
if __name__=="__main__":
    l,d,B,Y,h=[int(v) for v in sys.argv[1:6]]; F=PrimeConductorField(l,d)
    rels=relations(F,B,Y)
    good=[]                                           # keep the relations in which every prime ideal has exponent 0 or 1
    cache={}
    for c,coef,fac in rels:
        ok=True
        for q,k in fac:
            if q not in cache: cache[q]=span.periods(F,q)
            if sum(1 for j in range(F.N) if (c+sum(a*cache[q][(i+j)%F.N] for i,a in coef))%q==0)!=k: ok=False
        if ok: good.append((c,coef,fac))
    T,g=span.prove(F,span.relation_rows(F,good),0)
    print("field of degree %d and conductor %d: %d relations, T has %d primes (smallest %s); gcd of step (c): %d"%(d,l,len(good),len(T),T[:8],g))
    print("expected: %s"%("gcd 1" if h==1 else "gcd greater than 1 (class number %d)"%h))
    need(g==1 if h==1 else g>1,"TEST FAILED" if g!=0 else "TEST WITHOUT RESULT (the rows do not have full rank)")
    print("TEST PASSED")
